public float getFloat(final String property) {
  final String v = this.getProperty(property);
  if (null == v) {
    return -1;
  }
  try {
    return Float.parseFloat(v);
  } catch (NumberFormatException e) {
    // Handle the exception, e.g., log it or return a default value
    return -1;
  }
}
